// Parse CSV text from the previous node, validate rows, compute KPIs.
const text = $input.first().json.data;
const lines = text.trim().split(/\r?\n/);
const header = lines[0].split(',').map(h => h.trim().toLowerCase());
const required = ['date', 'region', 'product', 'units', 'revenue'];
const missing = required.filter(c => !header.includes(c));
if (missing.length) throw new Error('CSV is missing columns: ' + missing.join(', '));

const idx = Object.fromEntries(header.map((h, i) => [h, i]));
const rows = [];
let dropped = 0;
for (const line of lines.slice(1)) {
  const c = line.split(',');
  const date = new Date(c[idx.date]);
  const revenue = parseFloat(c[idx.revenue]);
  const units = parseInt(c[idx.units], 10) || 0;
  if (isNaN(date) || isNaN(revenue) || revenue < 0) { dropped++; continue; }
  rows.push({ date, month: c[idx.date].slice(0, 7), region: c[idx.region], product: c[idx.product], units, revenue });
}

const sumBy = (key) => {
  const out = {};
  for (const r of rows) out[r[key]] = (out[r[key]] || 0) + r.revenue;
  return Object.fromEntries(Object.entries(out).sort((a, b) => b[1] - a[1]).map(([k, v]) => [k, Math.round(v)]));
};
const round = (n) => Math.round(n * 10) / 10;

const months = [...new Set(rows.map(r => r.month))].sort();
const lastDate = new Date(Math.max(...rows.map(r => r.date)));
const firstDate = new Date(Math.min(...rows.map(r => r.date)));
const lastDayOfMonth = new Date(lastDate.getFullYear(), lastDate.getMonth() + 1, 0).getDate();
const lastMonthComplete = lastDate.getDate() >= lastDayOfMonth - 2;

const regionMonth = {};
for (const r of rows) {
  regionMonth[r.region] = regionMonth[r.region] || {};
  regionMonth[r.region][r.month] = (regionMonth[r.region][r.month] || 0) + r.revenue;
}
const mom = {};
if (months.length >= 2) {
  const [prev, last] = months.slice(-2);
  for (const [region, m] of Object.entries(regionMonth)) {
    if (m[prev]) mom[region] = round(((m[last] || 0) - m[prev]) / m[prev] * 100);
  }
}

const kpis = {
  period: `${firstDate.toISOString().slice(0, 10)} to ${lastDate.toISOString().slice(0, 10)}`,
  currency: 'not specified in the data',
  rows_used: rows.length,
  rows_dropped: dropped,
  total_revenue: Math.round(rows.reduce((s, r) => s + r.revenue, 0)),
  total_units: rows.reduce((s, r) => s + r.units, 0),
  monthly_revenue: Object.fromEntries(months.map(m => [m, Math.round(rows.filter(r => r.month === m).reduce((s, r) => s + r.revenue, 0))])),
  revenue_by_region_total_for_period: sumBy('region'),
  revenue_by_product_total_for_period: sumBy('product'),
  region_mom_change_pct: mom,
  last_month_is_partial: !lastMonthComplete,
  last_month_note: lastMonthComplete ? 'complete' : `${months[months.length - 1]} only has data up to day ${lastDate.getDate()}, so month-over-month changes understate it`,
};

return [{ json: { kpis } }];

