// Validate the LLM answer; fall back to a rule-based summary if anything is wrong.
const kpis = $('Compute KPIs').first().json.kpis;
const res = $input.first().json;
let bullets = null;
let source = 'AI';
const warnings = [];

try {
  const content = res.choices[0].message.content;
  const cleaned = content.replace(/^```(json)?/i, '').replace(/```$/, '').trim();
  const parsed = JSON.parse(cleaned);
  if (!Array.isArray(parsed.bullets) || parsed.bullets.length !== 3 || parsed.bullets.some(b => typeof b !== 'string' || !b.trim())) {
    throw new Error('AI output did not have exactly 3 bullets');
  }
  bullets = parsed.bullets.map(b => b.trim());
  if (bullets.some(b => /[$€£₹]/.test(b))) warnings.push('AI added a currency symbol that is not in the data');
} catch (e) {
  source = 'rule-based fallback';
  warnings.push('AI step failed: ' + (res.error?.message || e.message));
  const topRegion = Object.keys(kpis.revenue_by_region_total_for_period)[0];
  const topProduct = Object.keys(kpis.revenue_by_product_total_for_period)[0];
  const mom = kpis.region_mom_change_pct;
  const worst = Object.keys(mom).sort((a, b) => mom[a] - mom[b])[0];
  bullets = [
    `Total revenue of ${kpis.total_revenue.toLocaleString('en-IN')} from ${kpis.total_units} units (${kpis.period}); ${topRegion} is the top region and ${topProduct} the top product.`,
    `${worst} changed ${mom[worst]}% month over month, the weakest region${kpis.last_month_is_partial ? ' (last month is incomplete)' : ''}.`,
    `Review the ${worst} pipeline and pricing before next month's close.`,
  ];
}

return [{ json: { bullets, source, warnings, kpis } }];

// Build the HTML report (ready to email or save).
const { bullets, source, warnings, kpis } = $input.first().json;
const li = bullets.map(b => `<li>${b}</li>`).join('');
const rows = Object.entries(kpis.revenue_by_region_total_for_period)
  .map(([k, v]) => `<tr><td>${k}</td><td style="text-align:right">${v.toLocaleString('en-IN')}</td></tr>`).join('');
const warn = warnings.length ? `<p style="color:#b45309"><b>Checks:</b> ${warnings.join('; ')}</p>` : '';
const html = `<div style="font-family:Arial,sans-serif;max-width:640px">
<h2>Sales performance report</h2>
<p style="color:#666">Period: ${kpis.period} &middot; Summary source: ${source}${kpis.last_month_is_partial ? ' &middot; ' + kpis.last_month_note : ''}</p>
<h3>Summary</h3><ul>${li}</ul>${warn}
<h3>Revenue by region</h3><table cellpadding="6">${rows}</table></div>`;
return [{ json: { subject: `Sales report - ${kpis.period}`, html, bullets, source, warnings } }];
